CREATE TABLE vehicles (id BIGSERIAL PRIMARY KEY, plate VARCHAR(20) NOT NULL UNIQUE, type VARCHAR(20) NOT NULL CHECK (type IN ('FURGON','PICKUP','TRACTO','CARRETA')), brand VARCHAR(80), model VARCHAR(80), capacity_description VARCHAR(120), active BOOLEAN NOT NULL DEFAULT TRUE, observations TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicle_couplings (id BIGSERIAL PRIMARY KEY, tractor_id BIGINT NOT NULL REFERENCES vehicles(id), trailer_id BIGINT NOT NULL REFERENCES vehicles(id), start_at TIMESTAMP NOT NULL, end_at TIMESTAMP, reason VARCHAR(40) NOT NULL, observations TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_vehicle_coupling_types CHECK (tractor_id <> trailer_id));
CREATE INDEX ix_vehicle_coupling_tractor_active ON vehicle_couplings(tractor_id) WHERE end_at IS NULL;
CREATE INDEX ix_vehicle_coupling_trailer_active ON vehicle_couplings(trailer_id) WHERE end_at IS NULL;
